def text(key, fallback=None):
    lang = get_language()
    local = APP_TEXT.get(lang, {}).get(key)
    if local:
        return local
    try:
        value = t(key)
        return value if value else (fallback if fallback is not None else key)
    except Exception:
        return fallback if fallback is not None else key


