def _decode_image(image_bytes):
    array = np.frombuffer(image_bytes, dtype=np.uint8)
    image = cv2.imdecode(array, cv2.IMREAD_COLOR)
    if image is None:
        raise ValueError(ft("invalid_image"))
    return image


def _image_bytes_from_bgr(image):
    ok, encoded = cv2.imencode(".jpg", image, [int(cv2.IMWRITE_JPEG_QUALITY), 88])
    return encoded.tobytes() if ok else None


def _make_processing_images(image):
    """Create display images from the same functions used by model_utils."""
    blurred, gray, _ = preprocess_image(image)
    mask = create_grain_mask(image)
    contours = find_grain_contours(mask)

    threshold_view = cv2.cvtColor(mask, cv2.COLOR_GRAY2BGR)
    preprocess_view = cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)

    valid = []
    for contour in contours:
        if is_complete_single_grain(contour, image.shape):
            valid.append(contour)

    segmented = image.copy()
    cv2.drawContours(segmented, valid, -1, (0, 210, 90), 2)

    detection = image.copy()
    for contour in valid:
        x, y, w, h = cv2.boundingRect(contour)
        cv2.rectangle(detection, (x, y), (x + w, y + h), (0, 210, 90), 2)

    return {
        "uploaded": image,
        "threshold": threshold_view,
        "preprocess": preprocess_view,
        "segmentation": segmented,
        "detection": detection,
        "valid_contours": valid,
        "blurred": blurred,
    }


def _run_dynamic_prediction(image):
    """Run the existing model_utils pipeline and return actual per-image outputs."""
    if any(x is None for x in (preprocess_image, create_grain_mask, find_grain_contours, is_complete_single_grain, measure_grain, build_prediction_features, load_model)):
        raise RuntimeError("The existing model_utils.py pipeline could not be loaded.")

    visuals = _make_processing_images(image)
    rows = [measure_grain(image, contour) for contour in visuals["valid_contours"]]
    if not rows:
        return visuals, None, None

    features = build_prediction_features(rows)
    model = load_model()
    raw_prediction = model.predict(features)[0]
    prediction = _display_name(raw_prediction) if _display_name else str(raw_prediction)
    return visuals, rows, {"features": features.iloc[0].to_dict(), "prediction": prediction}


def _metric_value(features, key, digits=2):
    value = features.get(key)
    if value is None or pd.isna(value):
        return "—"
    return f"{float(value):.{digits}f}"


def _flow_img(key):
    return "data:image/jpeg;base64," + FLOW_REFERENCE_IMAGES[key]


