def _display_prediction_flow():
    """Static reference-style flow: exactly 4 cards on row 1 and 4 on row 2."""
    labels = [
        ft("uploaded"), ft("threshold"), ft("preprocess"), ft("segmentation"),
        ft("detection"), ft("measurements"), ft("features"), ft("model"),
    ]
    image_keys = [
        "uploaded", "threshold", "preprocess", "segmentation",
        "detection", "measurements", "features", "model",
    ]
    names = {
        "en": ["Sannalu", "Bondalu", "RNR 15048", "Swarna"],
        "te": ["సన్నాలు", "బొండాలు", "RNR 15048", "స్వర్ణ"],
        "hi": ["सन्नालु", "बोंडालु", "RNR 15048", "स्वर्ण"],
    }[get_language()]

    def make_row(start, end):
        cells = []
        for i in range(start, end + 1):
            label = labels[i - 1]
            key = image_keys[i - 1]
            if i == 8:
                names_html = "".join(
                    f"<div class='sp-model-name'>{name}</div>" for name in names
                )
                cells.append(
                    f"""
                    <div class='sp-model-card'>
                        <img class='sp-model-thumb' src='{_flow_img(key)}'>
                        <div class='sp-flow-num'>8</div>
                        <div class='sp-flow-name'>{label}</div>
                        <div class='sp-model-names'>{names_html}</div>
                    </div>
                    """
                )
            else:
                cells.append(
                    f"""
                    <div class='sp-flow-card'>
                        <img class='sp-flow-thumb' src='{_flow_img(key)}'>
                        <div class='sp-flow-num'>{i}</div>
                        <div class='sp-flow-name'>{label}</div>
                    </div>
                    """
                )
            if i < end:
                cells.append("<div class='sp-flow-arrow'>→</div>")
        return "".join(cells)

    st.markdown(
        f"""
        <div class='sp-flow-shell'>
            <div class='sp-flow-title'>⚙️ {ft("flow")}</div>
            <div class='sp-flow-row'>{make_row(1, 4)}</div>
            <div class='sp-flow-row'>{make_row(5, 8)}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

def _metric_value(features, key, digits=2):
    value = features.get(key) if features else None
    if value is None or pd.isna(value):
        return "—"
    return f"{float(value):.{digits}f}"


# ============================================================
# UPLOADED IMAGE + GRAIN MEASUREMENTS + FINAL PREDICTION
# ============================================================

def _render_dynamic_result_row(analysis):
    """Render the only three dynamic result cards.

    These cards update for every uploaded/captured image.
    Streamlit-native components are used here so no HTML tags
    can accidentally appear as visible text in the app.
    """
    features = analysis.get("model_result", {}).get("features") if analysis.get("model_result") else None
    prediction = analysis.get("model_result", {}).get("prediction") if analysis.get("model_result") else None
    rows = analysis.get("rows") or []

    # ------------------------------------------------------------
    # UPLOADED IMAGE PREVIEW
    # ------------------------------------------------------------
    # Use the actual uploaded image only.
    photo = analysis["visuals"]["uploaded"]

    # ------------------------------------------------------------
    # GRAIN MEASUREMENTS & FEATURES
    # ------------------------------------------------------------
    metric_rows = [
        (ft("count"), str(len(rows))),
        (ft("length"), _metric_value(features, "Average_Length_px") + " px"),
        (ft("width"), _metric_value(features, "Average_Width_px") + " px"),
        (ft("area"), _metric_value(features, "Average_Area_px2") + " px²"),
        (ft("perimeter"), _metric_value(features, "Average_Perimeter_px") + " px"),
        (ft("avg_r"), _metric_value(features, "Average_R")),
        (ft("avg_g"), _metric_value(features, "Average_G")),
        (ft("avg_b"), _metric_value(features, "Average_B")),
    ]

    # ------------------------------------------------------------
    # FINAL PREDICTION
    # ------------------------------------------------------------
    c1, c2, c3 = st.columns([1.15, 1.35, 1.15], gap="medium")

    with c1:
        with st.container(border=True):
            st.markdown("<span class='sp-bottom-card-marker'></span>", unsafe_allow_html=True)
            st.markdown(f"### 🖼️ {ft('preview')}")
            st.image(photo, use_container_width=True)

    with c2:
        # Only the measurements card gets a solid white background.
        with st.container(border=True, key="sp_measurement_card"):
            st.markdown("<span class='sp-bottom-card-marker'></span>", unsafe_allow_html=True)
            st.markdown(f"### 📊 {ft('metrics')}")
            for label, value in metric_rows:
                m1, m2 = st.columns([1.55, 1])
                with m1:
                    st.caption(label)
                with m2:
                    st.markdown(f"**{value}**")

    with c3:
        with st.container(border=True):
            st.markdown("<span class='sp-bottom-card-marker'></span>", unsafe_allow_html=True)
            st.markdown(f"### 🏆 {ft('result')}")
            st.markdown(f"**{ft('final')}**")
            st.markdown(
                f"<div style='background:#eef9f2;border:2px solid #168253;border-radius:14px;padding:18px 12px;text-align:center;'>"
                f"<div style='font-size:26px;'>🌾</div>"
                f"<div style='color:#075c37;font-size:20px;font-weight:900;'>{prediction or '—'}</div>"
                f"<div style='color:#168253;font-size:20px;margin-top:5px;'>✓</div>"
                f"</div>",
                unsafe_allow_html=True,
            )


