# PREDICTION ANALYZER
# ============================================================


def render_prediction():
    render_top_header()

    if predict_paddy_image_bytes is None or load_model is None:
        st.error(text("prediction_not_available", "Prediction model is not connected yet."))
        return

    # Fixed 4 + 4 flow is visible immediately and never changes.
    _display_prediction_flow()

    # ========================================================
    # UPLOAD IMAGE / SCAN GRAIN
    # ========================================================

    mode = st.radio(
        ft("choose"),
        [ft("upload"), ft("scan")],
        horizontal=True,
        key=f"prediction_mode_{get_language()}",
    )

    image_bytes = None
    if mode == ft("upload"):
        uploaded = st.file_uploader(
            ft("select_image"),
            type=["jpg", "jpeg", "png", "webp"],
            key="paddy_upload",
        )
        if uploaded is not None:
            image_bytes = uploaded.getvalue()
    else:
        captured = st.camera_input(ft("capture"), key="paddy_camera")
        if captured is not None:
            image_bytes = captured.getvalue()

    if image_bytes:
        try:
            image = _decode_image(image_bytes)
            if st.button(
                ft("analyze"),
                type="primary",
                use_container_width=True,
                key="analyze_prediction",
            ):
                with st.spinner(text("thinking", "Processing...")):
                    visuals, rows, model_result = _run_dynamic_prediction(image)
                st.session_state.prediction_analysis = {
                    "visuals": visuals,
                    "rows": rows,
                    "model_result": model_result,
                }
        except Exception as exc:
            st.error(f"{ft('invalid_image')} {type(exc).__name__}: {exc}")

    analysis = st.session_state.get("prediction_analysis")
    if analysis:
        _render_dynamic_result_row(analysis)

