def display_plan(plan):
    if not plan:
        return
    if plan.get("status") in {"rag_unavailable", "rag_error"}:
        st.error(plan.get("message", "Cultivation plan is unavailable."))
        return
    land_value = plan.get("land_size", "")
    if isinstance(land_value, dict):
        land_value = land_value.get("label", "")
    title_variety = plan.get("selected_variety", "Selected Variety")
    st.markdown(f"<div class='planner-result-title'>{title_variety} · {land_value}</div>", unsafe_allow_html=True)
    for label, value in _planner_facts(plan):
        st.markdown(f"<div class='fact-row'><span class='fact-label'>{label}</span><span class='fact-value'>{_translate_known_agri(value)}</span></div>", unsafe_allow_html=True)


def _short_answer_from_results(results, question):
    if not results:
        return "The verified Smart Paddy documents do not provide an answer for this question."
    q = str(question or "").strip().lower()
    combined = "\n".join(str(chunk.get("text", "")) if isinstance(chunk, dict) else str(chunk) for chunk, _ in results)
    low_combined = combined.lower()
    if re.search(r"\b(pest|pests|disease|diseases|blast|blight|insect|insects)\b", q):
        pest_terms = ["stem borer", "leaf folder", "panicle mite", "blast", "bacterial leaf blight", "bacterial blight", "sheath blight", "brown planthopper", "bph"]
        found = [term for term in pest_terms if term in low_combined]
        pest_names = [x.title() if x != "bph" else "BPH" for x in found if x in {"stem borer","leaf folder","panicle mite","brown planthopper","bph"}]
        disease_names = [x.title() for x in found if x in {"blast","bacterial leaf blight","bacterial blight","sheath blight"}]
        parts = []
        if pest_names: parts.append("Major documented pests: " + ", ".join(pest_names[:4]) + ".")
        if disease_names: parts.append("Major documented diseases: " + ", ".join(disease_names[:3]) + ".")
        if parts: return _translate_chat_text(" ".join(parts))
    if re.search(r"\b(fertilizer|fertiliser|fertilizers|fertilisers)\b", q):
        names = []
        for term in ["urea", "dap", "mop", "farmyard manure", "compost"]:
            if re.search(rf"\b{re.escape(term)}\b", combined, flags=re.I) and term not in names:
                names.append(term.upper() if term in {"dap","mop"} else term.title())
        if names: return _translate_chat_text("Recommended fertilizer names: " + ", ".join(names[:5]) + ".")
    banned = ("chatbot", "should be able", "must remain", "source", "document type", "similarity score", "selected variety", "land size", "the system", "do not invent", "can answer", "questions", "retrieved knowledge", "knowledge base")
    q_words = set(re.findall(r"[a-z0-9]+", q))
    candidates = []
    for chunk, score in results:
        txt = str(chunk.get("text", "")) if isinstance(chunk, dict) else str(chunk)
        for raw in re.split(r"(?<=[.!?])\s+|\n+", txt):
            line = re.sub(r"\s+", " ", raw).strip(" -:;,. ")
            low = line.lower()
            if len(line) < 18 or any(x in low for x in banned): continue
            overlap = len(q_words.intersection(set(re.findall(r"[a-z0-9]+", low))))
            if overlap: candidates.append((overlap * 5 + min(float(score), 1.0), line))
    if not candidates:
        return _translate_chat_text("The verified Smart Paddy documents do not provide a concise answer for this question.")
    candidates.sort(key=lambda x: (-x[0], len(x[1])))
    answer = candidates[0][1]
    quantity_question = bool(re.search(r"\b(how much|how many|quantity|amount|liters?|litres?|kg|kilograms?|labou?r|workers?)\b", q))
    if quantity_question and not re.search(r"\d+(?:\.\d+)?\s*(?:liters?|litres?|kg|kilograms?|members?|workers?|days?)\b", answer.lower()):
        return _translate_chat_text("The verified documents do not specify an exact quantity for this question.")
    return _translate_chat_text(answer)


